/**
 * Run the real OpenAI prompt conversion, then hand the request to an offline
 * stream once conversion reaches the fake fetch boundary.
 */
function createOpenAiContractModel() {
  const openAiModel = createOpenAI({
    apiKey: 'test-only',
    fetch: () =>
      Promise.resolve(
        new Response('data: [DONE]\n\n', {
          status: 200,
          headers: { 'content-type': 'text/event-stream' },
        }),
      ),
  }).responses('gpt-5.4-mini')
  // The mock still emits the pre-`ai@6` `finish` part, which the pinned core reads
  // as "no reason recorded" and reports as `'other'` — the reason a CUT stream
  // leaves. A scripted reply that completes must report `stop` like the real
  // adapter does, or the turn-close guard reads it as a cut-off reply.
  const offlineModel = withRepairedFinishReason(
    mockModel({ content: [{ type: 'text', text: 'Ready.' }] }),
  )

  return {
    specificationVersion: openAiModel.specificationVersion,
    provider: openAiModel.provider,
    modelId: openAiModel.modelId,
    supportedUrls: openAiModel.supportedUrls,
    doGenerate: (options) => offlineModel.doGenerate(options),
    doStream: async (
      options: Parameters<typeof openAiModel.doStream>[0],
    ): Promise<Awaited<ReturnType<typeof openAiModel.doStream>>> => {
      const probe = await openAiModel.doStream(options)
      await probe.stream.cancel()
      return offlineModel.doStream(options)
    },
  } satisfies typeof openAiModel
}

it('DOES save a fallback once the askUser Question has been answered', () => {
  // An answered Question (tool-result present) is no longer pending; a turn
  // that then dangles with no closing text should still terminate.
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('verknüpfe und korrigiere'),
      askUserCall(),
      toolResult({ answers: [{ pickedOptions: ['Helden des Waldes'] }] }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
})

it('closes the turn when nothing at all was written for it', () => {
  // The hole: no response rows, no finish reason, AND no failed row, so no
  // retryable bubble was ever written. Abstaining here left the GM with the
  // frontend's soft "you can keep chatting" over a turn that failed.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('ok parse jetzt die szenen und events')],
    finishReason: undefined,
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
})

it('does NOT save a fallback while an askUser Question is unanswered', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('verknüpfe und korrigiere'), askUserCall()],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(false)
})

it('does NOT surface an agent-facing guidance string verbatim', () => {
  const agentGuidance =
    'relationship-type-not-found — the slug is not active; call activeRelationshipTypes[] and retry with a valid slug'
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('link them'),
      toolCall('propose'),
      toolResult({ results: [{ ok: false, error: agentGuidance }] }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  // No fragment of the agent guidance leaks.
  expect(result.text).not.toContain(agentGuidance)
  expect(result.text).not.toContain('activeRelationshipTypes')
  expect(result.text).not.toContain('relationship-type-not-found')
  // Still terminates the turn with a warm, user-facing message.
  expect(result.text.toLowerCase()).toContain("wasn't able to finish")
})

it('does NOT treat a mixed text + tool-call assistant row as final text', () => {
  const mixedTextAndToolCall: FallbackSourceMessage = {
    message: {
      role: 'assistant',
      content: [
        { type: 'text', text: 'Let me check a few more entities…' },
        { type: 'tool-call', toolName: 'searchLibrary', toolCallId: 'tc-1', input: {} },
      ],
    },
  }
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('connect the dots'), mixedTextAndToolCall],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
})

it('does not save a fallback when a failed message already closed the turn', () => {
  // Nothing beyond the prompt, but the agent component persisted a failed
  // placeholder (rate limit / API throw) which the UI surfaces as retryable.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('go')],
    finishReason: undefined,
    retryableFailureSaved: true,
  })
  expect(result.shouldSave).toBe(false)
})

it('does not save a fallback when finishReason is error', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('go'), toolCall('propose')],
    finishReason: 'error',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(false)
})

it('drops to generic when failures span MIXED categories', () => {
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('do it'),
      toolCall('propose'),
      toolResult({
        results: [
          { ok: false, error: 'relationship-not-found' }, // not-found
          { ok: false, error: 'name must not be empty' }, // invalid-input
        ],
      }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text).not.toContain('relationship-not-found')
  expect(result.text).not.toContain('name must not be empty')
})

it('drops to the generic fallback for an unrecognized error code', () => {
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('do it'),
      toolCall('propose'),
      toolResult({
        results: [{ ok: false, error: 'some-internal-code-9001: stack trace here' }],
      }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text).not.toContain('some-internal-code-9001')
  expect(result.text).not.toContain('stack trace')
  expect(result.text).toBe(
    "I wasn't able to finish that. Want me to try a different approach, or rephrase what you're after?",
  )
})

it('ignores whitespace-only assistant text (that is not a real reply)', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('hi'), assistantText('   \n  ')],
    finishReason: 'stop',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
})

it('leaves a reply the model actually finished', () => {
  const cutOff = findCutOffMessage({
    savedMessages: [userPrompt('hi'), assistantText('Here you go!')],
    finishReason: 'stop',
    retryableFailureSaved: false,
  })
  expect(cutOff).toBeNull()
})

it('leaves a turn that produced no reply text for the fallback to close', () => {
  // Nothing to mark: the static terminator owns this turn, and the two are
  // mutually exclusive by construction.
  const cutOff = findCutOffMessage({
    savedMessages: [userPrompt('do it'), toolCall('manageLibrary')],
    finishReason: 'other',
    retryableFailureSaved: false,
  })
  expect(cutOff).toBeNull()
  expect(
    buildNoResponseFallback({
      savedMessages: [userPrompt('do it'), toolCall('manageLibrary')],
      finishReason: 'other',
      retryableFailureSaved: false,
    }).shouldSave,
  ).toBe(true)
})

it('leaves a turn the GM stopped, whose failed row is already its ending', () => {
  // Pressing Stop cuts the stream exactly like a fault does, and the partial
  // text lands the same way — but the component wrote the failed row from its
  // abort path. Marking anything here would tell a GM who cancelled on
  // purpose that they failed at something.
  const cutOff = findCutOffMessage({
    savedMessages: [userPrompt('parse the transcript'), assistantText('Let me')],
    finishReason: 'other',
    retryableFailureSaved: true,
  })
  expect(cutOff).toBeNull()
})

it('leaves a turn waiting on a pending askUser Question', () => {
  // #3834: the carousel IS the reply; a human-gated turn is not a cut one.
  const cutOff = findCutOffMessage({
    savedMessages: [userPrompt('which session?'), assistantText('Let me'), askUserCall()],
    finishReason: 'other',
    retryableFailureSaved: false,
  })
  expect(cutOff).toBeNull()
})

it('returns no fallback when the turn produced final assistant text', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('hi'), assistantText('Here you go!')],
    finishReason: 'stop',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(false)
})

it('returns the LAST reply row — the one the GM is left looking at', () => {
  const last = withId('m3', assistantText('and then'))
  const cutOff = findCutOffMessage({
    savedMessages: [
      withId('m1', userPrompt('go on')),
      withId('m2', assistantText('First I will')),
      last,
    ],
    finishReason: 'other',
    retryableFailureSaved: false,
  })
  expect(cutOff).toBe(last)
})

it('returns the fragment row so the turn can be marked failed', () => {
  const fragment = withId('m2', assistantText('Let me'))
  const cutOff = findCutOffMessage({
    savedMessages: [withId('m1', userPrompt('parse the transcript')), fragment],
    finishReason: 'other',
    retryableFailureSaved: false,
  })
  expect(cutOff).toBe(fragment)
})

it('saves a fallback when the model burned the step budget with no final text', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('go'), toolCall('propose')],
    finishReason: 'length',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text.trim().length).toBeGreaterThan(0)
})

it('saves a fallback when the step budget was exhausted with no response rows', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('do a lot')],
    finishReason: 'length',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
})

it('saves a friendly fallback when only tool calls/results were produced', () => {
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('create Bob'),
      toolCall('propose'),
      toolResult({ results: [{ ok: true, proposalId: 'p1' }] }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text.trim().length).toBeGreaterThan(0)
})

it('saves a friendly fallback when the turn finished cleanly with no response rows', () => {
  // finishReason 'stop' but no assistant/tool rows: a genuine empty
  // completion. Without a fallback the user message sits with no reply.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('hello?')],
    finishReason: 'stop',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text.toLowerCase()).toContain("wasn't able to finish")
})

it('says the turn stopped and nothing was saved, and offers a smaller retry', () => {
  // "Retry" alone is the wrong advice when the same context may fault again,
  // so the copy names what happened and offers splitting the turn up.
  const { text } = buildNoResponseFallback({
    savedMessages: [userPrompt('parse the transcript')],
    finishReason: undefined,
    retryableFailureSaved: false,
  })
  expect(text).toContain('nothing was saved')
  expect(text.toLowerCase()).toContain('send it again')
  expect(text.toLowerCase()).toContain('smaller steps')
})

it('stays generic-but-warm when no failed-tool reason is derivable', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('do the thing'), toolCall('searchLibrary')],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text.toLowerCase()).toContain("wasn't able to finish")
})

it('stays silent over a stopped turn even when it ran steps first', () => {
  // A GM pressing Stop mid-turn leaves a failed row and a finish reason that
  // is neither 'error' nor a real completion. Appending "I wasn't able to
  // finish that" would answer a deliberate cancellation with a retry nudge.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('do a lot'), toolCall('listLibrary')],
    finishReason: 'other',
    retryableFailureSaved: true,
  })
  expect(result.shouldSave).toBe(false)
})

it('stays silent over a stopped turn whose cancellation was never reported to the app', () => {
  // The component's onAsyncAbort path writes the failed row WITHOUT firing
  // the app's onError, so the decision must key off the saved row and not off
  // whether the app heard about the fault.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('parse the transcript')],
    finishReason: undefined,
    retryableFailureSaved: true,
  })
  expect(result.shouldSave).toBe(false)
})

it('still leaves a pending askUser Question alone when no failed message exists', () => {
  // The #3834 carve-out outranks the new close: a human-gated turn is not a
  // faulted one, and the carousel IS the reply.
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('which session?'), askUserCall()],
    finishReason: undefined,
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(false)
})

it('surfaces a friendly CATEGORY when every op failed with a known code', () => {
  const result = buildNoResponseFallback({
    savedMessages: [
      userPrompt('add a relationship'),
      toolCall('propose'),
      toolResult({
        results: [{ ok: false, error: 'relationship-type-not-found' }],
      }),
    ],
    finishReason: 'tool-calls',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(true)
  expect(result.text).toContain("I wasn't able to finish that")
  // A friendly not-found phrase — never the raw code.
  expect(result.text.toLowerCase()).toContain("couldn't find")
  expect(result.text).not.toContain('relationship-type-not-found')
})

it('treats a bare string assistant content as final text', () => {
  const result = buildNoResponseFallback({
    savedMessages: [userPrompt('hi'), assistantStringContent('Done.')],
    finishReason: 'stop',
    retryableFailureSaved: false,
  })
  expect(result.shouldSave).toBe(false)
})

/**
 * Decide whether to save a friendly fallback assistant message for a turn that
 * ended without a user-facing reply.
 *
 * Saves a fallback when the turn finished on a non-error reason and produced no
 * non-empty final assistant text. That covers three hangs:
 *   - ran a tool whose ops all failed, then stopped;
 *   - burned the `CHAT_MAX_STEPS` ceiling without a closing message;
 *   - returned an EMPTY completion (model said nothing — no response rows).
 *
 * Three cases are deliberately left alone:
 *   - `finishReason === 'error'` — already persisted as a retryable bubble;
 *   - a turn the component already closed with a `status:'failed'` row — a fault
 *     it reported, OR a stream the GM stopped; either way the turn already ends
 *     honestly and a second closing message would talk over it; and
 *   - a pending `askUser` Question — the turn is human-gated, the carousel is the
 *     reply, so the static terminator must not append a "couldn't finish" message.
 *
 * The faulted-stream case is the one that used to be assumed rather than checked
 * (#4814): with no failed row there is no retryable bubble, and abstaining left
 * the turn to the frontend's soft "you can keep chatting" net — advice that is
 * wrong for a turn that failed. It now closes honestly instead.
 *
 * Idempotent by construction: a turn that DID write final text returns
 * `shouldSave:false`, so re-running never clobbers a real reply.
 */
export function buildNoResponseFallback(input: NoResponseFallbackInput): NoResponseFallbackResult {
  const { savedMessages, finishReason, retryableFailureSaved } = input
  const noSave: NoResponseFallbackResult = { shouldSave: false, text: '' }

  if (finishReason === 'error') return noSave
  // An already-terminal turn outranks every close below. This covers the GM who
  // pressed Stop as well as a reported fault: telling someone to "send it again"
  // over a cancellation they chose is exactly the dishonest ending this module
  // exists to prevent.
  if (retryableFailureSaved) return noSave
  if (turnProducedFinalText(savedMessages)) return noSave
  // The turn-ending askUser Question (ADR-0127) reports finishReason 'tool-calls'
  // and writes no closing text; while its Answer is still pending the carousel IS
  // the reply, so the static terminator must not talk over it (mirrors the
  // truncation summary's identical carve-out).
  if (turnHasPendingQuestion(savedMessages)) return noSave
  // No finish reason at all means the turn recorded no step: the stream faulted
  // or was cut before the model produced anything. Nothing was saved and — per
  // the guard above — no failed row exists either, so this is the last layer that
  // can tell the GM the turn failed.
  if (!turnSavedAnyResponse(savedMessages) && finishReason === undefined) {
    return { shouldSave: true, text: FAULTED_TURN_TEXT }
  }

  const category = deriveFailureCategory(savedMessages)
  return { shouldSave: true, text: buildFallbackText(category) }
}

/**
 * Whether THIS row is the turn's user-facing reply text — the per-row half of
 * {@link turnProducedFinalText}, exported so a caller that must act ON that row
 * (rather than merely know one exists) selects it by the same rule.
 */
export function isFinalTextRow(row: FallbackSourceMessage): boolean {
  if (row.message?.role !== 'assistant') return false
  // A mixed text + tool-call row is the model mid-step, not a closing reply.
  if (assistantHasToolCallPart(row.message)) return false
  if (assistantText(row.message).length > 0) return true
  return typeof row.text === 'string' && row.text.trim().length > 0
}

/**
 * Whether the turn produced any non-empty final assistant text (already closed).
 *
 * A row that has BOTH text and an unfinished tool-call part is NOT terminal: the
 * model narrated and then wanted to call another tool, so its text is mid-turn
 * commentary, not a closing reply. Such mixed rows are excluded so a
 * budget-exhausted turn that happened to emit interim narration still routes to
 * the summary/fallback path rather than being mistaken for a finished turn.
 */
export function turnProducedFinalText(savedMessages: readonly FallbackSourceMessage[]): boolean {
  return savedMessages.some(isFinalTextRow)
}

/**
 * Terminate a reply the stream cut mid-sentence by marking the fragment row the
 * SDK already persisted as failed (#4814).
 *
 * The row is left where it is, text and all — the GM watched those words arrive
 * and deleting them would be its own dishonesty. Only its terminal state changes:
 * the client API's `'error'` maps to the persisted `status:'failed'`, which is the
 * SAME state the component's own fail paths write, so the fragment renders with
 * the retry affordance under it and `chats.retry` can target it by order like any
 * other failed turn. No new state, and no second message talking over the first.
 *
 * Best-effort: the fragment is already saved, so a patch failure must not fail the
 * turn — it degrades to today's behaviour (a fragment with no error).
 */
async function markMessageCutOff(ctx: ActionCtx, message: MessageDoc): Promise<void> {
  try {
    await getChatAgentForWrites().updateMessage(ctx, {
      messageId: message._id,
      patch: {
        // `updateMessage` replaces the row's message, so the fragment is passed
        // back unchanged: this call changes the turn's STATUS, not its content.
        message: message.message ?? { role: 'assistant', content: '' },
        status: 'error',
        error: CUT_OFF_TURN_ERROR,
      },
    })
  } catch (error) {
    console.error(
      createError({
        status: 500,
        message: 'A cut-off chat reply could not be marked as failed',
        why: 'The stream ended mid-reply, but the patch marking the saved fragment retryable failed',
        fix: 'Inspect the Agent message update failure; the GM must resend the message rather than retry it',
        cause: error,
        context: { messageId: message._id },
      }),
    )
  }
}

/**
 * Await a turn's finish reason without letting a turn that produced NOTHING take
 * the whole action down with it (#4814).
 *
 * `result.finishReason` never resolves `undefined` on `ai@6`: it resolves a
 * non-null reason, or it REJECTS when the turn recorded no step at all — a stream
 * the GM stopped, or a provider fault before the first step finished. Awaiting it
 * bare threw past every close path below, so the one turn the terminal guarantee
 * exists to close (#3735) was the one turn that never reached it.
 *
 * The rejection is an outcome, not an incident: it means "this turn produced no
 * step", which is exactly what an absent finish reason already denotes downstream.
 * Nothing is logged for it — the honest ending is written below, and the routine
 * case is a GM pressing Stop.
 */
async function settleTurnFinishReason(result: {
  finishReason: PromiseLike<unknown>
}): Promise<TurnFinishReason> {
  try {
    return (await result.finishReason) as TurnFinishReason
  } catch {
    return undefined
  }
}

/**
 * Internal streaming action.
 * Called from chats.send mutation via ctx.scheduler.runAfter(0, ...).
 *
 * Streams the agent response and saves it to the thread.
 * The client subscribes via chats.messages (with streamArgs) to get real-time
 * streaming deltas via Convex's reactive query system.
 */
export const streamChatResponse = internalAction({
  args: {
    chatId: v.id('chats'),
    workspaceId: v.id('workspaces'),
    threadId: v.string(),
    userId: v.string(),
    message: v.string(),
    // The turn's full ContextRef set (#3938 W3) — the message's own context refs
    // PLUS a synthesized `library_item` ref for the open Library item (the
    // back-compat fold of the bespoke `currentLibraryItemId` wire arg) and a
    // synthesized `session_entity` ref when the chat path minted/linked a prep
    // Session. The action walks this set through the ContextProvider registry ONCE
    // (the single per-turn context loop) to compose the system-prompt blocks and
    // stash the per-turn tool-context (activeSkillId, prepSessionEntityId,
    // activeCanvasId). Absent ⇒ a plain turn with no open surface.
    contextRefs: v.optional(v.array(contextRefValidator)),
    imageAssetIds: v.optional(v.array(v.id('assets'))),
    textFiles: v.optional(v.array(chatTextFileValidator)),
    /**
     * Set only on retry (chats.retry): the already-saved user prompt message to
     * regenerate a response for. When present the action skips saving a new user
     * turn and streams via the `promptMessageId` path in buildStreamArgs.
     */
    regeneratePromptMessageId: v.optional(v.string()),
    /**
     * Set only on retry: the stale failed-response message id(s) to delete once
     * pre-stream setup has succeeded (durable — see chats.retry).
     */
    staleMessageIds: v.optional(v.array(v.string())),
    // The Skills the User invoked inline for this turn (ADR-0110). Derived from
    // the `/slug` mentions in the message body at send time (deduped, first-
    // occurrence order). Each slug's instructions are pre-injected into the
    // turn's system block. NOT persisted: the sent message renders golden `/slug`
    // spans re-derived from its own body text, so no sidecar is written.
    skillSlugs: v.optional(v.array(v.string())),
    // (#3869 Slice 3, ADR-0163): the captureFragment ids whose distill lifecycle
    // this turn is serving. Set only by `captures.distill`; absent on every
    // ordinary chat send. After the turn stream completes, the completion hook
    // below transitions these fragments from `distilling` to `distilled` and
    // stamps `distilledAt` (AC6). Best-effort — a failure is logged but never
    // fails the turn (the reply is already saved).
    captureDistillIds: v.optional(v.array(v.id('captureFragments'))),
  },
  handler: async (
    ctx,
    {
      chatId,
      workspaceId,
      threadId,
      userId,
      message,
      contextRefs,
      imageAssetIds,
      textFiles,
      regeneratePromptMessageId,
      staleMessageIds,
      skillSlugs,
      captureDistillIds,
    },
  ) => {
    const resolvedImageAssetIds = imageAssetIds ?? []
    const resolvedTextFiles = textFiles ?? []
    const agent = getChatAgentForWrites()
    const { thread } = await agent.continueThread(ctx, {
      threadId,
      userId,
    })

    // Skills discovery + dynamic-load surface is gated on the `skills` flag
    // (ADR-0107, ADR-0063). Both the in-prompt `## Available skills` catalog AND
    // the `loadSkill` tool's availability read THE SAME flag so they never
    // desync: flag off → no catalog block and `loadSkill` absent from the turn's
    // tool set (S1 AC7), keeping `main` behaviour identical. Fail-closed off
    // prod; on dev/preview all flags read ON (lib/featureFlags).
    // The skills surface is gated on the `skills` flag (ADR-0107, ADR-0063);
    // read it concurrently with the schema-tools flag — neither consumes the
    // other's result. Flag off ⇒ the corresponding tool is absent from this
    // turn's tool set (`assembleTurnTools` below), keeping a flag-off turn
    // byte-identical to `main`. Fail-closed off prod; on dev/preview all flags
    // read ON (lib/featureFlags). The askUser HITL Question tool is always-on
    // now (ADR-0127, graduated off `ask-user-question`), so it carries no flag.
    // ADR-0166 sticky Mode: read the Chat's persisted active stance slug
    // concurrently with the flags (neither consumes the other's result), so the
    // co-GM stance composes on EVERY turn while a Mode is active — plain turns,
    // askUser/approval resume turns, and retries all reach this read even though
    // they schedule the action with no `skillSlugs`. `null` ⇒ default Build (no
    // stance), keeping the turn byte-identical to the no-stance composition.
    const [
      skillsEnabled,
      schemaToolsEnabled,
      eventsEnabled,
      agentCuesEnabled,
      tasksEnabled,
      activeStanceSlug,
    ] = await Promise.all([
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: 'skills',
        userId,
      }),
      // ADR-0136: the Approval-gated Library Schema editing tool is offered to
      // the model only behind `library-schema-tools`. Read it concurrently —
      // independent of the other flags. Flag off ⇒ `editLibrarySchema` is absent
      // from `assembleTurnTools` below, keeping the turn byte-identical to `main`.
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: 'library-schema-tools',
        userId,
      }),
      // ADR-0147 amendment: the authored-Event chat birth path is offered to the model
      // only behind `events`. Read concurrently — independent of the other flags. Flag
      // off ⇒ the `<events_protocol>` section is omitted from `buildSystemPrompt` AND
      // the `event_create` handler rejects the op server-side; the op itself always
      // appears in the `propose` tool schema (rides the always-on propose tool).
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: 'events',
        userId,
      }),
      // ADR-0165: the single client-driving `directAttention` tool + the
      // `<agent_cues_protocol>` prompt fragment are offered to the model only
      // behind `agent-cues`. Read concurrently — independent of the other flags.
      // Flag off ⇒ `directAttention` is absent from `assembleTurnTools` below AND
      // the prompt section is omitted from `buildSystemPrompt`, so the turn is
      // byte-identical to `main` (the client Cue executor + overlay also never
      // mount, gated on the same flag).
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: AGENT_CUES_FLAG.key,
        userId,
      }),
      // PRD #4218: the single chat-scoped `manageTasks` tool + the
      // `<tasks_protocol>` prompt slot + the `<task_list>` injection are offered
      // to the model only behind `chat-tasks`. Read concurrently — independent
      // of the other flags. Flag off ⇒ `manageTasks` is absent from
      // `assembleTurnTools` below, the prompt slot is omitted from
      // `buildSystemPrompt`, and no `<task_list>` block is injected, so the turn
      // is byte-identical to `main` (the TaskProgress widget also never mounts,
      // gated on the same flag).
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: CHAT_TASKS_FLAG.key,
        userId,
      }),
      // ADR-0166: the Chat's sticky Mode stance slug (or null for default Build).
      ctx.runQuery(internal.chats.internalActiveStance.internalReadActiveStance, {
        chatId,
        workspaceId,
      }),
    ])

    // Per-Mode flag gate (#3913 generalized by #4044, epic #4042 C2): stance
    // APPLICATION is gated on the PERSISTED slug's OWN flag
    // (`stanceFlagKeyForSlug`: `prep-mode` for prep, `debrief` for debrief) —
    // read serially AFTER the stance slug resolves (the key depends on it), and
    // only when a stance is actually persisted, so a default Build turn issues
    // no extra query. Flag off (or an unknown/non-Mode slug) ⇒ the persisted
    // slug is ignored and no stance composes, so the turn is byte-identical to
    // the no-stance composition (e.g. a chat entered a Mode while on-flag, then
    // the flag was rolled back). Fail-closed off prod; dev/preview read all-on.
    const stanceFlagKey =
      activeStanceSlug === null ? undefined : stanceFlagKeyForSlug(activeStanceSlug)
    const stanceEnabled =
      stanceFlagKey !== undefined &&
      (await ctx.runQuery(internal.flags.internalIsEnabled, {
        key: stanceFlagKey,
        userId,
      }))

    // Resolve the sticky stance slug → its mechanism-slot overrides (built-in only:
    // a non-Mode / unknown slug resolves to undefined). Passed into buildStreamArgs
    // so buildSystemPrompt folds the Mode's co-GM slots over the base registry.
    const stance =
      !stanceEnabled || activeStanceSlug === null
        ? undefined
        : resolveStanceForSlug(activeStanceSlug)

    // Resolve both skills reads CONCURRENTLY when enabled. The per-turn catalog
    // (workspace-scoped built-in ∪ workspace-owned) and the explicitly-invoked
    // Skill's full instructions are fully independent — neither consumes the
    // other's result — so a single Promise.all collapses what was two serial
    // action→internalQuery round-trips into one, cutting the latency the User
    // feels before the stream starts. The flag-off short-circuit issues neither
    // query, keeping a flag-off turn byte-identical to `main`.
    //
    // ADR-0110 §inline /slug: every recognized inline `/slug` mention pre-injects
    // the named Skill's FULL instructions into this turn's system block, skipping
    // the loadSkill discovery round-trip; framed as subordinate guidance and
    // composed BELOW the principles + catalog (ADR-0107 §8). A turn may invoke
    // MORE THAN ONE Skill, so we resolve every slug's instructions concurrently
    // and stack the resolved blocks in first-occurrence order. An unknown slug
    // resolves to null and is dropped (the turn still streams); the slugs came
    // from the recognizer over the available-slug list.
    // ADR-0156 `skills`-flag softening: the per-slug instruction pre-inject runs
    // for the slugs `chats.send` already validated (built-in usage is ungated, so
    // `/prep-session` injects its guidance off-flag), while the DISCOVERY catalog
    // (`internalListAvailable`) + the `loadSkill` tool stay gated (the sidebar's
    // surface). So inject invoked slugs always; resolve the catalog only on-flag.
    const resolvedSlugs = skillSlugs ?? []
    const [catalogSkills, invokedInstructions] = await Promise.all([
      skillsEnabled
        ? ctx.runQuery(internal.skills.internalListAvailable, { workspaceId })
        : Promise.resolve(undefined),
      Promise.all(
        resolvedSlugs.map((slug) =>
          ctx.runQuery(internal.skills.internalLoadInstructions, { workspaceId, slug }),
        ),
      ),
    ])

    // ADR-0159 decision 5: hide the Skills the GM already invoked with `/slug`
    // from the per-turn `loadSkill` catalog. Their full instructions are already
    // injected into this turn's system block (above), so listing them again would
    // only tempt the model to waste a step re-loading them. The catalog then
    // carries ONLY the Skills the GM did NOT name — `loadSkill`'s dynamic-discovery
    // role.
    const skillsCatalogSection =
      catalogSkills !== undefined
        ? `${promptSkillsPreamble}\n\n${buildCatalogSection(buildPerTurnCatalog(catalogSkills, resolvedSlugs))}`
        : undefined

    const invokedSkillSection = renderInvokedSkillSection(
      invokedInstructions.filter((instructions): instructions is string => instructions !== null),
    )

    // #3938 W3 — the single per-turn context loop. Walk the turn's ContextRef set
    // through the ContextProvider registry ONCE (behind the internal-query seam,
    // since this action runtime has no `ctx.db`): resolve each ref within the
    // chat's workspace scope (ADR-0015 Layer 2), collect the ordered prompt blocks
    // (open-item grounding, then active-canvas — `refs[]` order preserves today's
    // ordering), and shallow-merge the tool-context values (activeSkillId,
    // prepSessionEntityId, activeCanvasId). This folds the three pre-#3938 ad-hoc
    // mechanisms (the bespoke `currentLibraryItemId` grounding + the
    // active_surface/session_entity ctx-stashes) into one walk. Resolution degrades
    // gracefully — a stale/cross-workspace ref resolves to nothing and is skipped,
    // so the turn still streams. A turn with no refs walks an empty set.
    const turnContext =
      contextRefs === undefined || contextRefs.length === 0
        ? { promptBlocks: [] as string[], toolCtx: {} as Record<string, unknown> }
        : await ctx.runQuery(
            internal.chats.context.internalResolveTurnContext.internalResolveTurnContext,
            { threadId, refs: contextRefs },
          )
    // The post-turn prep_activity hook reads the resolved Session id (ADR-0156); the
    // open-Skill / active-canvas tool-ctx values are stashed onto the action ctx
    // wholesale below, so only the Session id needs a named binding here.
    const prepSessionEntityId = (turnContext.toolCtx as { prepSessionEntityId?: Id<'entities'> })
      .prepSessionEntityId

    const imageRefs =
      resolvedImageAssetIds.length === 0
        ? []
        : await ctx.runQuery(internal.chats.messageImages.resolveForModelInput, {
            workspaceId,
            imageAssetIds: resolvedImageAssetIds,
          })

    // Issue these two always-needed request-time reads concurrently so neither
    // serializes on the time-to-first-token path. Both depend only on the
    // handler-entry args (userId, workspaceId) — neither consumes the other's
    // result — so a single Promise.all is correct:
    //   - the effective reply language (#1795): workspace override ?? user
    //     preference ?? 'en', threaded into the per-turn system prompt below;
    //   - the per-turn reasoning-effort flag (#1737), resolved at request time
    //     (actions have no ctx.db) via the same internal seam the frontend
    //     boundary uses, keyed on this turn's userId — flag-OFF keeps the #1175
    //     launch default (CHAT_PROVIDER_OPTIONS, reasoningEffort 'high').
    const [outputLanguage, dynamicEffortEnabled] = await Promise.all([
      ctx.runQuery(internal.chats.internalForLanguage.internalResolveEffectiveChatLanguage, {
        userId,
        workspaceId,
      }),
      ctx.runQuery(internal.flags.internalIsEnabled, {
        key: DYNAMIC_REASONING_EFFORT_FLAG,
        userId,
      }),
    ])

    // The effort router only feeds provider options for a reasoning driver, so
    // the whole effort machinery (the open-proposal signal + the scheduled
    // classifier) is gated on this one static check for the active model.
    const activeModelIsReasoning = isReasoningModel(CHAT_MODEL_ID)

    // Whether a create flow (a pending Proposal) is already open for the chat is
    // a router signal consumed ONLY when the effort flag is on AND the driver is a
    // reasoning model (flag-OFF, or a non-reasoning driver, resolves to the static
    // default regardless of signals). Gate the lookup behind both so a turn that
    // would discard the result never serializes on — or fails to first-token on — it.
    const hasOpenProposal =
      dynamicEffortEnabled && activeModelIsReasoning
        ? await ctx.runQuery(internal.proposals.internalOpenProposal.hasOpenProposal, { chatId })
        : false

    // On retry we regenerate against the already-saved prompt message, so never
    // save a new one — even for image turns (the images are re-resolved below
    // and re-injected via the context handler).
    const savedPrompt =
      regeneratePromptMessageId !== undefined || imageRefs.length === 0
        ? undefined
        : await agent.saveMessage(ctx, {
            threadId,
            userId,
            ...(resolvedTextFiles.length === 0
              ? { prompt: message }
              : {
                  message: {
                    role: 'user',
                    content: buildUserContent(message, [], resolvedTextFiles),
                  },
                }),
            skipEmbeddings: true,
          })

    // PRD #4218: the per-turn `<task_list>` injection. Only when `chat-tasks` is
    // on AND the chat has a non-empty Task List do we read the row and render the
    // deterministic block (content + status only — `activeForm` is UI-only). The
    // read is gated on the flag so a flag-off turn issues no extra query and stays
    // byte-identical to `main`; an empty/absent list renders `undefined`, so a
    // task-free on-flag turn injects nothing (the cache-stable prefix is never
    // destabilised — dynamic-tail placement, ADR-0149). Rides the workspace-context
    // blocks region, after the stable system+tools prefix (the `<resolved_entities>`
    // memo pattern).
    const taskListBlock = tasksEnabled
      ? renderTaskListBlock(
          await ctx.runQuery(internal.chats.tasks.functions.internalReadChatTasks, {
            chatId,
            workspaceId,
          }),
        )
      : undefined
    const turnContextBlocks =
      taskListBlock !== undefined
        ? [...turnContext.promptBlocks, taskListBlock]
        : turnContext.promptBlocks

    // Build stream args. Image URLs are injected through a per-call context
    // handler below so the Agent SDK persists only the text prompt.
    // On retry, regenerate against the already-saved prompt message (no new user
    // turn). Otherwise the image path may have just saved one (savedPrompt).
    const resolvedPromptMessageId = regeneratePromptMessageId ?? savedPrompt?.messageId
    const streamArgs = buildStreamArgs({
      message,
      contextBlocks: turnContextBlocks,
      imageRefs,
      textFiles: resolvedTextFiles,
      outputLanguage,
      ...(resolvedPromptMessageId !== undefined
        ? { promptMessageId: resolvedPromptMessageId }
        : {}),
      ...(skillsCatalogSection !== undefined ? { skillsCatalogSection } : {}),
      ...(invokedSkillSection !== undefined ? { invokedSkillSection } : {}),
      ...(schemaToolsEnabled ? { schemaToolsEnabled } : {}),
      ...(eventsEnabled ? { eventsEnabled } : {}),
      ...(agentCuesEnabled ? { agentCuesEnabled } : {}),
      // PRD #4218: compose the `<tasks_protocol>` slot only when `chat-tasks` is
      // on, matching the `manageTasks` tool gate below so guidance + tool never
      // desync. Flag-off omits it, keeping the turn byte-identical to `main`.
      ...(tasksEnabled ? { manageTasksEnabled: tasksEnabled } : {}),
      stance,
    })

    if (savedPrompt !== undefined && resolvedImageAssetIds.length > 0) {
      await ctx.runMutation(internal.chats.messageImages.attachToPromptMessage, {
        workspaceId,
        chatId,
        messageId: savedPrompt.messageId,
        imageAssetIds: resolvedImageAssetIds,
      })
    }

    // Per-turn reasoning-effort routing (Issue #1737). The router reads signals
    // already present on the turn — message text, attachment presence, and the
    // pending-Proposal flag resolved above — so deriving the effort adds no
    // time-to-first-token. Flag-OFF keeps the #1175 launch default
    // (CHAT_PROVIDER_OPTIONS, reasoningEffort 'high').
    const hasAttachments = resolvedImageAssetIds.length > 0 || resolvedTextFiles.length > 0
    const providerOptions = buildProviderOptions(
      { message, hasAttachments, hasOpenProposal },
      // ADR-0149: pin the OpenAI prompt cache to this conversation's thread so
      // every multi-step call in the turn routes to one cache entry. The driver
      // id gates whether reasoning options are emitted at all (a non-reasoning
      // driver gets none) — see buildProviderOptions.
      { dynamicEffortEnabled, threadId, modelId: CHAT_MODEL_ID },
    )

    // Phase-2 (Issue #1739): when the gate is ON, run the gpt-4.1-nano classifier
    // in a SEPARATE scheduled job — never awaited in front of thread.streamText,
    // so it adds no time-to-first-token (the current turn already has its
    // synchronous heuristic effort above). The one classifier call amortizes
    // turn-prep (effort + tool-need hint / search query) for subsequent turns.
    // Flag-OFF: the action is not scheduled, so no classifier call is made.
    // Also skipped for a non-reasoning driver — the effort it produces is never
    // sent to the model (buildProviderOptions omits reasoning options), so the
    // classifier call would be pure wasted cost.
    if (dynamicEffortEnabled && activeModelIsReasoning) {
      // Best-effort, never awaited: a scheduling failure must not block — or
      // abort — the active stream (the classifier is documented as "scheduled,
      // never awaited before first token"). Fire-and-forget with a logged catch.
      void ctx.scheduler
        .runAfter(0, internal.chats.classifierAction.classifyTurnAction, {
          message,
          hasAttachments,
          hasOpenProposal,
        })
        .catch((error: unknown) => {
          console.error(
            createError({
              status: 500,
              message: 'Chat turn classification was not scheduled',
              why: 'The scheduler rejected the detached turn-classification action',
              fix: 'Inspect the Convex scheduler failure; the active chat stream does not need to be retried',
              cause: error,
              context: { chatId, threadId },
            }),
          )
        })
    }

    // Retry only: now that all pre-stream setup has succeeded, drop the stale
    // failed-response part(s) so the regenerated answer replaces them. Deferring
    // the delete to here (rather than in chats.retry) keeps the user's failed
    // turn retryable if any setup above throws — and if streamText itself fails,
    // the Agent component persists a fresh failed message at the same order.
    if (staleMessageIds !== undefined && staleMessageIds.length > 0) {
      await agent.deleteMessages(ctx, { messageIds: staleMessageIds })
    }

    // Stream the response, saving deltas as we go. The tool set is assembled
    // PER TURN (ADR-0107 §6): always the feature tools, plus `loadSkill` only
    // when the `skills` flag is on. This `tools` override flows through the SDK
    // per-call seam (@convex-dev/agent 0.6.2), overriding the agent
    // constructor's set — the static module-load agent cannot vary tools per
    // turn. Gated on the SAME flag read as the catalog block. The dynamic
    // `providerOptions` (Issue #1737) carry the per-turn reasoning effort.
    // ADR-0149: the always-on Chat context handler. It preserves today's image
    // re-injection (the per-turn image URLs ride in the user content so the SDK
    // persists only the text prompt) AND adds the deterministic tool-result
    // compaction + resolved-entities memo over the in-flight (unchanged) Messages.
    const imageUserContent =
      imageRefs.length === 0 ? undefined : buildUserContent(message, imageRefs, resolvedTextFiles)
    const contextHandler = buildChatContextHandler(imageUserContent)

    // ADR-0128 active-surface routing (#3938 W3): the Agent SDK builds each tool's
    // ctx by spreading THIS action ctx (`toolCtx = { ...ctx, userId, threadId, … }`),
    // so stash the per-turn tool-context the registry walk resolved (above) onto the
    // ctx here. The shallow-merged values are the open-surface write targets a tool
    // /op defaults from: `activeSkillId` (the `propose` tool reads it via
    // `getToolActiveSkillId` so `skill_write` paints in the open Skill editor) and
    // `activeCanvasId` (the open-canvas board read default). Assigning the whole
    // resolved record keeps the action agnostic to which kinds were open — a new
    // tool-ctx-bearing context kind needs no change here (#3938 L4/L5). An empty
    // record (no open surface) assigns nothing, byte-identical to a plain turn.
    Object.assign(ctx, turnContext.toolCtx)

    // ADR-0159 decision 5: stash the turn's explicitly-invoked `/slug` set on the
    // same per-turn ctx so the `loadSkill` tool (reading via
    // `getToolInvokedSkillSlugs`) returns the tiny `{ alreadyLoaded: true }` ack
    // for a slug already injected above, instead of re-fetching its instructions.
    // Set unconditionally (empty array for a turn with no inline `/slug`) so the
    // tool reads a definite value rather than racing the ctx-stash default.
    ;(ctx as typeof ctx & { invokedSkillSlugs?: readonly string[] }).invokedSkillSlugs =
      resolvedSlugs

    // ADR-0167 Distill provenance: stash the capture-fragment ids surfaced to the
    // agent this turn on the same per-turn ctx so the `propose` tool (reading via
    // `getToolTurnCaptureFragmentIds`) can resolve each Proposal's `distilledFrom`
    // — intersecting the agent's cited `sourceCaptureIds` against this surfaced set
    // (no forging) and defaulting to the whole set when the agent cites nothing.
    // Populated from `captureDistillIds` (set only by `captures.distill`); set
    // UNCONDITIONALLY (empty array on an ordinary turn, like `invokedSkillSlugs`)
    // so the tool reads a definite value and a non-Distill Proposal carries no
    // `distilledFrom`.
    ;(ctx as typeof ctx & { turnCaptureFragmentIds?: readonly string[] }).turnCaptureFragmentIds =
      captureDistillIds ?? []

    // The deterministic resurfacing engine is offered when the prep-session Skill
    // is active this turn (explicit /slug invocation, ADR-0156) OR when the chat
    // is in sticky Prep Mode (ADR-0166 activeStanceSlug). A sticky Prep turn has
    // the co-GM stance applied, so resurfaceForPrep should be available even
    // though /prep-session is not in skillSlugs. The Skill calls
    // `resurfaceForPrep` by id; a non-prep turn stays byte-identical to `main`.
    // `prepActive` also drives the post-turn prep_activity hook, so the two
    // checks stay in sync.
    const prepActive =
      isPrepSkillActive(skillSlugs) ||
      (stanceEnabled && activeStanceSlug === PREP_SESSION_SKILL_SLUG)
    // ADR-0171 (#4044): the sticky debrief Mode ALSO gets the prep read tools
    // (resurfaceForPrep) so the agent grounds "what did you prep?" against the
    // linked Session — but it does NOT drive the prep_activity hook (a debrief
    // turn is not prep engagement), hence the separate tools-only widening.
    const prepToolsActive = prepActive || (stanceEnabled && activeStanceSlug === DEBRIEF_SKILL_SLUG)

    let result: Awaited<ReturnType<typeof thread.streamText>> | undefined
    // Set when consumeStream threw (provider rate-limit / API error). That path
    // is already persisted by the Agent component as a `status:'failed'` message
    // and surfaced as a retryable notice, so the no-response fallback below must
    // NOT fire for it (the user already has a terminal, retryable bubble).
    let streamThrew = false
    // The rich provider error from the streaming `onError` event, captured so the
    // failed message's error can be re-persisted legibly below. The Agent
    // component persists it via `String(error)` → "[object Object]" for the
    // plain-object errors OpenAI streams (insufficient_quota, rate limits),
    // erasing the code/message the UI's `classifyChatError` needs.
    let capturedStreamError: unknown
    try {
      result = await thread.streamText(
        {
          ...streamArgs,
          providerOptions,
          // Per-step output ceiling (ADR-0159, #3841): hard-bounds the
          // model's own streamed output so a runaway reply/reasoning can't grow
          // the vendored agent's stream-delta document past the backend limit and
          // throw uncatchably. Far above any legitimate turn; hitting it ends the
          // step with finishReason 'length', handled soft by the turn-close guard.
          maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS,
          // The component's streaming wrapper persists the failed message FIRST
          // (lossy `[object Object]`), then forwards this `onError`. We capture the
          // rich event so the post-stream block re-persists a legible string.
          onError: (event: { error?: unknown }) => {
            capturedStreamError = event.error ?? event
          },
          tools: assembleTurnTools({
            skillsEnabled,
            schemaToolsEnabled,
            prepActive: prepToolsActive,
            // The single client-driving `directAttention` tool is offered ONLY
            // when `agent-cues` is on this turn (ADR-0165) — flag off keeps the
            // turn byte-identical to `main`.
            agentCuesEnabled,
            // PRD #4218: the `manageTasks` task-list tool is offered ONLY when
            // `chat-tasks` is on this turn — flag off keeps the turn
            // byte-identical to `main`.
            tasksEnabled,
          }),
        },
        {
          saveStreamDeltas: true,
          contextHandler,
        },
      )

      // ADR-0110: no per-message Skill sidecar is written. The inline `/slug`
      // mentions live verbatim in the saved user message body, so the sent-message
      // render re-derives the golden spans from that text on every read — there is
      // nothing to persist separately (the chatMessageSkills sidecar is retired;
      // its rows are deleted by m20260614_dropChatMessageSkillsRows, and slice D
      // narrows the schema in a later release).

      // Consume the stream (this blocks until generation completes or is aborted)
      await result.consumeStream()
    } catch (error) {
      // A provider failure (rate limit / API error) is already persisted by the
      // Agent component as a failed message (`status: 'failed'` + `error`) via
      // its onError → fail path. The chat UI surfaces that as a retryable error
      // notice (chats.retry). Swallow here so this scheduled action exits cleanly
      // rather than emitting scheduler error-log noise for a handled condition.
      // We do NOT return: a turn that ran tools and raised Proposals before
      // failing mid-stream still needs the rekey below.
      console.error(
        createError({
          status: 502,
          message: 'Chat response streaming failed',
          why: 'The model provider or stream consumer failed before the chat turn completed',
          fix: 'Inspect the provider error and retry the failed chat turn',
          cause: error,
          context: { chatId, threadId },
        }),
      )
      streamThrew = true
    }

    // BUG-1 (Epic #65): rekey any Proposals this turn raised from the prompt
    // message id (the only id a write tool knows mid-generation) to the
    // assistant message bubble's UI key, so the chat deep-link mounts on the
    // agent turn. Guarded on `result` so it also runs for a partial-success turn
    // that raised Proposals before the stream failed (result is set whenever
    // streamText resolved, even if consumeStream later threw).
    if (result !== undefined) {
      const bubbleKey = assistantBubbleKey(threadId, result.savedMessages, result.order)
      if (bubbleKey !== null) {
        await ctx.runMutation(
          internal.proposals.internalRekeyMessageId.internalRekeyProposalMessageId,
          { chatId, fromMessageId: result.promptMessageId, toMessageId: bubbleKey },
        )
      }
    }

    // Legible-error re-persistence: the Agent component's streaming `onError`
    // already persisted this turn's failed message with `String(error)` —
    // "[object Object]" for the plain-object errors OpenAI streams
    // (`insufficient_quota` billing exhaustion, rate limits). That erases the
    // provider code/message the UI's `classifyChatError` reads, so EVERY streaming
    // provider failure renders as the same generic "couldn't finish that response".
    // Re-persist a legible string built from the captured `onError` event so the GM
    // sees an accurate "temporarily unavailable" / "try again in a moment" notice.
    // Best-effort: never throws — on any miss the existing (lossy) error stands, so
    // the worst case is today's behavior. The failed message is located via
    // `listMessages` (NOT `result.savedMessages`, which an errored turn often omits —
    // see assistantBubbleKey). Only the error string is changed; status stays
    // `failed` so the turn remains retryable.
    if (capturedStreamError !== undefined) {
      const legibleError = serializeStreamError(capturedStreamError)
      if (legibleError !== undefined) {
        try {
          // The component's fail path persisted exactly `errorToString(error.error)`
          // — `error.message` for an `Error`, lossy `String(...)` otherwise. Match on
          // that exact string so we only ever patch THIS turn's failed message and
          // can never clobber a concurrent turn's different (already legible) error.
          const lossyError =
            capturedStreamError instanceof Error
              ? capturedStreamError.message
              : // eslint-disable-next-line @typescript-eslint/no-base-to-string -- intentionally reproduces the component's lossy `String(...)` (→ "[object Object]") so the match targets exactly the message its fail path persisted
                String(capturedStreamError)
          const recent = await agent.listMessages(ctx, {
            threadId,
            paginationOpts: { numItems: 5, cursor: null },
          })
          const failed = recent.page.find((m) => m.status === 'failed' && m.error === lossyError)
          if (failed !== undefined && failed.error !== legibleError) {
            await agent.updateMessage(ctx, {
              messageId: failed._id,
              patch: {
                message: failed.message ?? { role: 'assistant', content: '' },
                // The client API takes 'success' | 'error' and maps 'error' to
                // the persisted MessageStatus 'failed' — the row STAYS in the
                // retryable failed state; only its error string is upgraded.
                status: 'error',
                error: legibleError,
              },
            })
          }
        } catch (error) {
          console.error(
            createError({
              status: 500,
              message: 'The legible chat stream error could not be persisted',
              why: 'The failed message lookup or update failed after the stream error was already recorded',
              fix: 'Inspect the Agent message persistence failure; the user can still retry the failed chat turn',
              cause: error,
              context: { chatId, threadId },
            }),
          )
        }
      }
    }

    // Turn-close guard (ADR-0159 decision 3, #chat-hang): when the stream consumed
    // NORMALLY but the turn produced no final assistant text, nothing above wrote a
    // terminal message, so the placeholder assistant row dangles and the UI spins
    // "Working…" forever. Two close paths:
    //
    //   - Budget-exhausted truncation (the model burned CHAT_MAX_STEPS mid-workflow
    //     with no closing message and NO pending askUser) closes with a dynamic,
    //     localized SUMMARY turn — exactly one additional `streamText` with tools
    //     DISABLED, instructed to summarize in the GM's language what it did and list
    //     next options. Tools-disabled bounds cost (10 steps + 1 summary, decision 7)
    //     and guarantees it cannot loop or bloat the stream. This replaces the static
    //     English fallback for the truncation case.
    //   - Every other dangling turn (a tool whose ops all failed, an empty completion)
    //     keeps the static `buildNoResponseFallback` last-resort terminator.
    //
    // `askUser` also reports finishReason 'tool-calls' (it is turn-ending); the
    // truncation branch fires ONLY when no Question is pending, so it never talks over
    // a Question the agent is waiting on. Skipped when the stream threw (the
    // failed/retryable bubble already exists) and idempotent: a turn that DID write
    // final text never reaches either close path.
    if (result !== undefined && !streamThrew) {
      const finishReason = await settleTurnFinishReason(result)
      const savedMessages = result.savedMessages
      const fireSummary = shouldFireSummaryTurn(finishReason, savedMessages)

      // A summary generation that itself throws (provider error) must still leave a
      // terminal turn (AC4/AC12), so a failed summary degrades to the static
      // terminator below rather than re-dangling the row.
      let summaryClosedTurn = false
      if (fireSummary) {
        // The localized truncation summary. Disable tools so this generation cannot
        // do more work, loop, or grow the stream — it can only narrate a close.
        const languageSection = buildOutputLanguageSection(outputLanguage)
        const summaryInstruction = buildTruncationSummaryInstruction(
          outputLanguage,
          languageSection,
        )
        // PRD #4218 / contract #4203 §6: the tools-disabled summary turn cannot
        // call manageTasks, but its prompt must carry the CURRENT `<task_list>`
        // block so the summary honestly reports the remaining pending items.
        // Re-read the row here (not the pre-turn snapshot) — the exhausted turn
        // just mutated statuses, and the post-turn state is what the GM needs
        // reported. Flag-off (or task-free) turns append nothing.
        const summaryTaskListBlock = tasksEnabled
          ? renderTaskListBlock(
              await ctx.runQuery(internal.chats.tasks.functions.internalReadChatTasks, {
                chatId,
                workspaceId,
              }),
            )
          : undefined
        // When a Mode stance is active, prepend the composed system prompt so
        // the summary generation stays in the co-GM voice rather than reverting
        // to default Build behavior mid-conversation.
        const summaryBase =
          stance === undefined
            ? summaryInstruction
            : `${buildSystemPrompt({ stance })}\n\n${summaryInstruction}`
        const summarySystem =
          summaryTaskListBlock === undefined
            ? summaryBase
            : `${summaryBase}\n\n${summaryTaskListBlock}`
        try {
          const summary = await thread.streamText(
            {
              promptMessageId: result.promptMessageId,
              providerOptions,
              system: summarySystem,
              tools: {},
              // Same output ceiling as the main stream (ADR-0159, #3841): the
              // summary only narrates a close, but the cap keeps even this
              // tools-disabled generation from growing a crashing stream document.
              maxOutputTokens: CHAT_MAX_OUTPUT_TOKENS,
            },
            // ADR-0149: thread the always-on contextHandler so the summary
            // generation receives the compacted, memo-enriched context rather
            // than the full uncompacted post-truncation transcript. The summary
            // only narrates (tools disabled), so the memo is safe to include.
            { saveStreamDeltas: true, contextHandler },
          )
          await summary.consumeStream()
          // The summary only closes the turn if it actually produced final
          // assistant text. A tools-disabled generation can still come back empty
          // (provider hiccup / empty completion); treating that as closed would
          // suppress the static fallback below and re-dangle the turn — the exact
          // bug this branch eliminates. When the summary is empty we leave
          // summaryClosedTurn false so the static terminator still fires.
          summaryClosedTurn = turnProducedFinalText(summary.savedMessages)
          // Stamp the truncation-summary message ID on the chat document so the
          // messages query can set metadata.truncated = true on the row —
          // fulfilling the producer side of the frontend's readTruncated()
          // contract (ADR-0159 decision 7). Only when the summary closed the turn
          // (it wrote final text). Best-effort: a marker failure must NOT fail the
          // turn (the summary is already persisted).
          const summaryMessageId = summaryClosedTurn
            ? summary.savedMessages.find((m) => m.message?.role === 'assistant')?._id
            : undefined
          if (summaryMessageId !== undefined) {
            await ctx
              .runMutation(internal.chats.truncationMarker.stampTruncationSummaryMessage, {
                chatId,
                messageId: summaryMessageId,
              })
              .catch((markerError: unknown) => {
                console.error(
                  createError({
                    status: 500,
                    message: 'Chat truncation marker could not be persisted',
                    why: 'The summary completed, but the mutation that marks it as truncated failed',
                    fix: 'Inspect the truncation-marker mutation failure; the saved summary remains available',
                    cause: markerError,
                    context: { chatId, threadId },
                  }),
                )
              })
          }
        } catch (error) {
          console.error(
            createError({
              status: 502,
              message: 'Chat truncation summary generation failed',
              why: 'The tools-disabled summary turn did not complete after the chat exhausted its step budget',
              fix: 'Inspect the model provider failure; the static fallback closes the current turn',
              cause: error,
              context: { chatId, threadId },
            }),
          )
        }
      }
      // A turn that wrote a finished reply on any reason but the cut-stream
      // stand-in `'other'` reaches NEITHER close path below, so it needs neither
      // the decision nor the extra read that feeds it. Skipping keeps the
      // ordinary answered turn — the overwhelming majority — at zero added
      // queries on the close path.
      const mayNeedClosing = finishReason === 'other' || !turnProducedFinalText(savedMessages)
      // The static fallback is RETAINED as the last-resort terminator (ADR-0159
      // decision 3): the all-tools-failed / empty-completion cases, AND the
      // truncation case if its summary generation failed above — so the turn is
      // never left non-terminal.
      if (!summaryClosedTurn && mayNeedClosing) {
        // Read whether the component already closed this turn with a terminal
        // `status:'failed'` row rather than inferring it from `capturedStreamError`
        // (#4814): the abort path that a GM pressing Stop takes writes that row
        // WITHOUT ever forwarding `onError`, so the in-process proxy would answer
        // a deliberate cancellation with "send it again".
        const retryableFailureSaved = await turnHasSavedFailure(ctx, {
          threadId,
          order: result.order,
        })
        // A turn the stream cut mid-reply left a FRAGMENT persisted as an ordinary
        // successful reply (#4814) — content, no error, nothing to retry. There is
        // no message to append there: the fragment itself is what is dishonest, so
        // it is marked failed in place. Mutually exclusive with the fallback below,
        // which only ever fires for a turn that produced no reply text at all.
        const cutOff = findCutOffMessage({ savedMessages, finishReason, retryableFailureSaved })
        if (cutOff !== null) {
          await markMessageCutOff(ctx, cutOff)
        } else {
          const fallback = buildNoResponseFallback({
            savedMessages,
            finishReason,
            retryableFailureSaved,
          })
          if (fallback.shouldSave) {
            await agent.saveMessage(ctx, {
              threadId,
              userId,
              promptMessageId: result.promptMessageId,
              message: { role: 'assistant', content: fallback.text },
              skipEmbeddings: true,
            })
          }
        }
      }

      // ADR-0159 decision 7 monitoring: emit a telemetry event on EVERY
      // budget-exhausted limit-stop (the truncation case AND the genuinely-stuck
      // budget-exhausted cases that route to the static fallback), carrying the
      // steps used, the step ceiling, the invoked Skill slug(s), and whether the
      // summary turn fired — so truncation rate is observable per skill and the
      // ceiling can be tuned from real usage. Best-effort: a telemetry failure must
      // never fail the turn (the reply is already saved).
      if (isBudgetExhausted(finishReason, savedMessages)) {
        await ctx
          .runMutation(internal.chats.truncationTelemetry.emitTurnTruncated, {
            workspaceId,
            chatId,
            userId,
            stepsUsed: countToolSteps(savedMessages),
            maxSteps: CHAT_MAX_STEPS,
            skillSlugs: resolvedSlugs,
            // Use summaryClosedTurn (the OUTCOME) not fireSummary (the DECISION)
            // so the telemetry signal accurately records whether the tools-disabled
            // summary generation SUCCEEDED, not merely whether we attempted it.
            summaryFired: summaryClosedTurn,
          })
          .catch((error: unknown) => {
            console.error(
              createError({
                status: 500,
                message: 'Chat truncation telemetry was not emitted',
                why: 'The telemetry mutation failed after a budget-exhausted chat turn completed',
                fix: 'Inspect the truncation telemetry mutation; the completed chat turn does not need to be retried',
                cause: error,
                context: { chatId, threadId },
              }),
            )
          })
      }
    }

    // ADR-0156 prep_activity hook: when the prep-session Skill was active this
    // turn AND the message carried a Session Entity Context Ref (ADR-0128), emit
    // the granular per-turn activity signal. A non-prep turn (no prep-session
    // slug, or no Session ref) emits nothing — keeping the turn unchanged. The
    // hook reads the user email + counts captures inside the mutation; it is
    // best-effort (never awaited in front of the user's reply, already saved).
    if (prepActive && prepSessionEntityId !== undefined) {
      // Best-effort: a telemetry failure must never fail the turn (the reply is
      // already saved). Use `.catch` so any mutation throw is swallowed here.
      await ctx
        .runMutation(internal.prepSessions.activityHook.emitPrepActivity, {
          workspaceId,
          chatId,
          sessionEntityId: prepSessionEntityId,
          userId,
        })
        .catch((error: unknown) => {
          console.error(
            createError({
              status: 500,
              message: 'Prep-session activity was not emitted',
              why: 'The prep activity mutation failed after the chat reply was saved',
              fix: 'Inspect the prep activity mutation; the completed chat turn does not need to be retried',
              cause: error,
              context: { chatId, threadId, sessionEntityId: prepSessionEntityId },
            }),
          )
        })
    }

    // ADR-0163 §4 (#3869 Slice 3): Distill completion hook — transition the
    // served captureFragments from `distilling` to `distilled` with `distilledAt`
    // now that the prep-session turn has finished (AC6). Present only on turns
    // seeded by `captures.distill`; ordinary chat turns carry no `captureDistillIds`
    // and skip this entirely. Best-effort: a fragment-patch failure is logged but
    // must never fail the turn (the reply is already saved, AC6 is provenance-only).
    //
    // Skipped when the stream threw: a failed distill turn must NOT stamp its
    // fragments `distilled` — that would hide the failure from retry/UI flows and
    // strand the fragments out of the `distilling` state they should retry from.
    if (!streamThrew && captureDistillIds !== undefined && captureDistillIds.length > 0) {
      await ctx
        .runMutation(internal.captures.internalCompleteDistill.internalMarkFragmentsDistilled, {
          captureIds: captureDistillIds,
        })
        .catch((error: unknown) => {
          console.error(
            createError({
              status: 500,
              message: 'Capture fragments were not marked as distilled',
              why: 'The distill-completion mutation failed after the chat turn completed',
              fix: 'Inspect the fragment state and retry the distillation if the fragments remain distilling',
              cause: error,
              context: { chatId, threadId },
            }),
          )
        })
    }
  },
})

/**
 * Whether the Agent component already closed this turn with a terminal, retryable
 * `status:'failed'` message — the evidence that the turn has an honest ending and
 * the static terminator must stay quiet (#4814).
 *
 * Read from the persisted row rather than inferred from the app's `onError`,
 * because the component has two fail paths and only one of them reaches the app:
 * `streamText`'s `onError`, and the `DeltaStreamer`'s `onAsyncAbort` — the path a
 * GM pressing Stop takes. Both write this row; only the first fires `onError`.
 * Scoped to THIS turn's `order` so an older failed turn in the same thread can
 * never silence a live one.
 */
async function turnHasSavedFailure(
  ctx: ActionCtx,
  { threadId, order }: { threadId: string; order: number },
): Promise<boolean> {
  const failed = await getChatAgentForWrites().listMessages(ctx, {
    threadId,
    statuses: ['failed'],
    paginationOpts: { numItems: FAILED_ROW_SCAN_LIMIT, cursor: null },
  })
  return failed.page.some((message) => message.order === order)
}

/**
 * Build the real chat agent wired to a deterministic, offline mock language
 * model. The agent component, streaming, and message persistence run REAL —
 * only the model is faked (ADR-0060). Use in chat-backend and `useChat`
 * (issue #492) tests to inject a scripted reply with no live LLM call.
 *
 * @example
 *   const { agent } = createChatAgentWithMockModel({ text: 'Hello adventurer' })
 *   setChatAgentForTesting(agent)
 *   // ...drive chats.send via the harness; streamChatResponse uses `agent`...
 *   clearChatAgentForTesting()
 */
export function createChatAgentWithMockModel(options: MockChatModelOptions = {}): {
  agent: Agent
} {
  const { text, chunkDelayInMs = 0, initialDelayInMs = 0, streamError, streamChunks } = options
  // A fresh stream per `doStream` call, so a multi-step turn replays the script
  // instead of reading a stream the previous step already drained. The cast is
  // the single bridge from the structural {@link MockStreamChunk} to the SDK's
  // own part union — everything else on the args object stays type-checked.
  const doStream: MockModelDoStream =
    streamChunks === undefined
      ? undefined
      : ((() =>
          Promise.resolve({
            stream: simulateReadableStream({
              chunks: [...streamChunks],
              initialDelayInMs,
              chunkDelayInMs,
            }),
            request: { body: {} },
            response: { headers: {} },
          })) as MockModelDoStream)
  const model = mockModel({
    chunkDelayInMs,
    initialDelayInMs,
    ...(text === undefined ? {} : { content: [{ type: 'text', text }] }),
    // `mockModel` types `fail.error` as `string` but forwards it verbatim into
    // the emitted `{ type: 'error', error }` stream part, so a plain object
    // faithfully reproduces the OpenAI provider shape this seam exists to test.
    ...(streamError === undefined ? {} : { fail: { error: streamError as string } }),
    ...(doStream === undefined ? {} : { doStream }),
  })
  const agent = createChatAgent(withRepairedFinishReason(model))
  return { agent }
}

/**
 * Restate a mock `finish` stream part in the shape the pinned `ai` core reads.
 *
 * `@convex-dev/agent@0.6.4`'s `mockModel` emits the pre-`ai@6` finish part
 * (`finishReason: 'stop'`), but `ai@6.0.208` reads `chunk.finishReason.unified`.
 * A bare string has no `.unified`, so the core records NO reason for the step and
 * resolves its stand-in `'other'` — the same reason a stream that ended without a
 * `finish` chunk leaves behind. Every mock-driven turn therefore looks like a cut
 * stream, which is the opposite of what these seams are for: a scripted reply that
 * completes must report `stop`, exactly as the production OpenAI adapter does.
 *
 * Only bare-string finish reasons are rewritten, so a mock that already speaks the
 * current shape (or any real provider part) passes through untouched.
 */
export function repairMockFinishReason<Chunk>(
  stream: ReadableStream<Chunk>,
): ReadableStream<Chunk> {
  return stream.pipeThrough(
    new TransformStream<Chunk, Chunk>({
      transform(chunk, controller) {
        const part = chunk as { type?: unknown; finishReason?: unknown }
        if (part.type === 'finish' && typeof part.finishReason === 'string') {
          controller.enqueue({
            ...part,
            finishReason: { unified: part.finishReason, raw: part.finishReason },
          } as Chunk)
          return
        }
        controller.enqueue(chunk)
      },
    }),
  )
}

/**
 * Wrap a mock language model so its streamed `finish` part reaches the `ai` core
 * in the current shape (see {@link repairMockFinishReason}). Returns the same
 * model instance — `mockModel` exposes `doStream` as a plain assignable slot.
 */
export function withRepairedFinishReason<Model extends StreamingMockModel>(model: Model): Model {
  const inner = model.doStream.bind(model)
  const doStream: StreamingMockModel['doStream'] = async (options) => {
    const result = await inner(options)
    return { ...result, stream: repairMockFinishReason(result.stream) }
  }
  return Object.assign(model, { doStream })
}

const doStream: StreamingMockModel['doStream'] = async (options) => {
  const result = await inner(options)
  return { ...result, stream: repairMockFinishReason(result.stream) }
}

/**
 * Install the real chat agent wired to a model whose stream is scripted chunk by
 * chunk, so a turn can end in ways the canned scripts cannot express — above all
 * WITHOUT a `finish` chunk, which is what leaves the turn with no recorded step
 * and the finish-reason promise rejected.
 */
function installScriptedStream(streamChunks: readonly MockStreamChunk[]): void {
  setChatAgentForTesting(createChatAgentWithMockModel({ streamChunks }).agent)
}

it('does not also append a closing message beside it', async () => {
  const t = makeConvexTest()
  const { rows } = await sendAndReadThread(t, 'parse the transcript')

  const spoken = rows
    .filter((row) => row.status !== 'failed' && row.message?.role === 'assistant')
    .map((row) => row.text ?? '')
  expect(spoken).toHaveLength(0)
})

it('does not record the fragment as a successful reply', async () => {
  const t = makeConvexTest()
  const { rows, streamJobState } = await sendAndReadThread(t, 'parse the transcript')

  expect(streamJobState).toBe('success')
  const assistant = rows.filter((row) => row.message?.role === 'assistant')
  expect(assistant.map((row) => row.status)).toEqual(['failed'])
})

it('does not talk over that bubble with a second closing message', async () => {
  const t = makeConvexTest()
  const { rows } = await sendAndReadThread(t, 'connect the dots')

  // The turn already ends honestly and is already retryable. A second message
  // here would be the mirror-image bug: a GM who pressed Stop takes this same
  // path — the component writes the failed row from `onAsyncAbort` without ever
  // firing the app's `onError` — and would be told to "send it again" over a
  // cancellation they chose. The decision keys off the saved row, so it is not
  // fooled by which fail path wrote it.
  const spoken = rows
    .filter((row) => row.status !== 'failed' && row.message?.role === 'assistant')
    .map((row) => row.text ?? '')
  expect(spoken).toHaveLength(0)
})

it('is left exactly as the model wrote it', async () => {
  const t = makeConvexTest()
  const { rows, streamJobState } = await sendAndReadThread(t, 'prep tonight')

  expect(streamJobState).toBe('success')
  const assistant = rows.filter((row) => row.message?.role === 'assistant')
  expect(assistant).toHaveLength(1)
  expect(assistant[0]?.text).toContain('Here is your prep.')
  // The status matters as much as the text: a reply the model FINISHED must not
  // pick up the cut-off treatment. Asserting only the text would let a turn that
  // reports a reason the SDK cannot read be silently marked failed under an
  // intact answer.
  expect(assistant[0]?.status).toBe('success')
  expect(assistant[0]?.error).toBeUndefined()
})

it('keeps the words the model did get out, and makes the turn retryable', async () => {
  const t = makeConvexTest()
  const { rows } = await sendAndReadThread(t, 'parse the transcript')

  // The fragment is what the GM already read on screen — deleting it would be
  // its own dishonesty. It stays, and the failed status puts the component's
  // retry affordance under it (`chats.retry` targets the failed row's order).
  const failed = rows.filter((row) => row.status === 'failed')
  expect(failed).toHaveLength(1)
  expect(failed[0]?.text).toBe('Let me')
  expect(failed[0]?.error ?? '').toContain('cut off')
})

it('leaves the GM the retryable failed bubble the component wrote', async () => {
  const t = makeConvexTest()
  const { rows } = await sendAndReadThread(t, 'parse the transcript')

  const failed = rows.filter((row) => row.status === 'failed')
  expect(failed).toHaveLength(1)
  expect(failed[0]?.error ?? '').toContain('No output generated')
})

it('runs the turn to completion instead of dying on the missing finish reason', async () => {
  const t = makeConvexTest()
  const { streamJobState } = await sendAndReadThread(t, 'ok parse jetzt die szenen und events')

  // Before the guard, the rejected finish reason escaped the action entirely:
  // the close path, the truncation telemetry and the completion hooks below it
  // never ran, and the turn ended as an operator-visible crash.
  expect(streamJobState).toBe('success')
})

function makeConvexTest() {
  const t = convexTest(schema, modules)
  agentTest.register(t)
  liveTests.push(t)
  return t
}

/** Send one message, run every scheduled job serially, and read back the thread. */
async function sendAndReadThread(t: ReturnType<typeof makeConvexTest>, message: string) {
  const seeded = await seedConvexWorkspace(t)
  const { chatId } = await seeded.authT.mutation(api.chats.send, {
    workspaceId: seeded.workspace.id,
    message,
  })
  await t.finishAllScheduledFunctions(vi.runAllTimers)

  const chat = await t.run(async (ctx) => ctx.db.get('chats', chatId))
  // `chats.send` always stamps the thread; a missing chat is a broken harness, and
  // an empty threadId would silently read an empty thread and fail every assertion
  // below with "no rows" instead of naming the real cause.
  if (chat === null) throw new Error(`chats.send returned a chat id with no chat row: ${chatId}`)
  const messages = await seeded.authT.query(api.chats.messages, {
    workspaceId: seeded.workspace.id,
    threadId: chat.agentThreadId,
    paginationOpts: { cursor: null, numItems: 30 },
    order: 'asc',
  })
  const streamJob = await t.run(async (ctx) => {
    // A single send fans out a handful of scheduled jobs; take a bounded page well
    // above that rather than collecting the whole system table.
    const jobs = await ctx.db.system.query('_scheduled_functions').take(20)
    return jobs.find((job) => job.name.includes('streamChatResponse'))
  })
  return { rows: messages.page as unknown as ThreadRow[], streamJobState: streamJob?.state.kind }
}
